#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.ComponentModel;
using MVZ2.Models;
using MVZ2.View.Level;
using MVZ2Logic.Inputs;
using MVZ2Logic.Models;
using PVZEngine;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace MVZ2.Customize
{
    public class TeleporterTeamLayoutTileUI : MonoBehaviour
    {
        public void SetHighlightColor(Color color)
        {
            tileHighlight.color = color;
        }
        public void ClearLayerModels()
        {
            foreach (var model in models.Values)
            {
                Destroy(model.gameObject);
            }
            models.Clear();
        }
        public void AddEntityModel(NamespaceID layer, IModelBuilder modelBuilder)
        {
            if (models.ContainsKey(layer))
                return;
            var model = Instantiate(modelContainerTemplate, modelsRoot);
            model.gameObject.SetActive(true);
            model.SetModel(modelBuilder);
            models.Add(layer, model);
        }
        public void RemoveEntityModel(NamespaceID layer)
        {
            if (models.TryGetValue(layer, out var container))
            {
                Destroy(container.gameObject);
                models.Remove(layer);
            }
        }
        private void Awake()
        {
            modelContainerTemplate.gameObject.SetActive(false);
            handler.OnPointerInteraction += OnPointerInteractionCallback;
        }
        private void OnPointerInteractionCallback(LevelPointerInteractionHandler handler, PointerEventData eventData, PointerInteraction interaction)
        {
            OnPointerInteraction?.Invoke(this, eventData, interaction);
        }
        public event Action<TeleporterTeamLayoutTileUI, PointerEventData, PointerInteraction>? OnPointerInteraction;
        [SerializeField]
        private Image tileHighlight = null!;
        [SerializeField]
        private Transform modelsRoot = null!;
        [SerializeField]
        private LevelPointerInteractionHandler handler = null!;
        [SerializeField]
        private ModelContainer modelContainerTemplate = null!;
        private readonly Dictionary<NamespaceID, ModelContainer> models = new Dictionary<NamespaceID, ModelContainer>();
    }
}
